local assertNotNull = require("assert_not_null")

--- @class Vector2D
--- @field x number
--- @field y number

--- @type Vector2D
local Vector2D = {}
Vector2D.__index = Vector2D

--- @return Vector2D
-- Create an x/y pair, using zero for any missing coordinate.
function Vector2D.new(x, y)
    return setmetatable({ x = x or 0, y = y or 0 }, Vector2D)
end

-- Accept either {x=..., y=...} or {x, y} and make a vector.
function Vector2D.fromPosition(position)
    return Vector2D.new(position[1] or position.x, position[2] or position.y)
end

-- Store the eight coordinate pairs once instead of constructing all eight vectors
-- for every lookup. The returned vector is still a fresh object: callers may edit it.
local directionOffsets = {
    [defines.direction.north] = { 0, -1 },
    [defines.direction.northeast] = { 1, -1 },
    [defines.direction.east] = { 1, 0 },
    [defines.direction.southeast] = { 1, 1 },
    [defines.direction.south] = { 0, 1 },
    [defines.direction.southwest] = { -1, 1 },
    [defines.direction.west] = { -1, 0 },
    [defines.direction.northwest] = { -1, -1 }
}

--- @param direction defines.direction
--- @return Vector2D
-- Convert a compass direction to movement on the map; north decreases y.
function Vector2D.fromDirection(direction)
    assertNotNull(direction)
    local offset = directionOffsets[direction]
    if offset then
        return Vector2D.new(offset[1], offset[2])
    end
    return nil
end

--- @return defines.direction
-- Convert a unit movement vector using the same game directions as fromDirection().
function Vector2D:toDirection()
    if self.x == 0 and self.y == -1 then
        return defines.direction.north
    elseif self.x == 1 and self.y == -1 then
        return defines.direction.northeast
    elseif self.x == 1 and self.y == 0 then
        return defines.direction.east
    elseif self.x == 1 and self.y == 1 then
        return defines.direction.southeast
    elseif self.x == 0 and self.y == 1 then
        return defines.direction.south
    elseif self.x == -1 and self.y == 1 then
        return defines.direction.southwest
    elseif self.x == -1 and self.y == 0 then
        return defines.direction.west
    elseif self.x == -1 and self.y == -1 then
        return defines.direction.northwest
    end
    return nil
end

--- @return Vector2D
-- Return movement in the opposite direction without changing this vector.
function Vector2D:reverse()
    return Vector2D.new(self.x * -1, self.y * -1)
end

-- Multiply both coordinates to make movement longer or shorter.
function Vector2D:scale(magnitude)
    return Vector2D.new(self.x * magnitude, self.y * magnitude)
end

--- @return Vector2D
-- Allow a + b to add both coordinates, returning a new vector.
function Vector2D:__add(other)
    return Vector2D.new(self.x + other.x, self.y + other.y)
end

--- @return Vector2D
-- Allow a - b to calculate the coordinate difference.
function Vector2D:__sub(other)
    return Vector2D.new(self.x - other.x, self.y - other.y)
end

--- @return boolean
-- Compare coordinates rather than comparing which table holds them.
function Vector2D.__eq(ca, cb)
    return ca.x == cb.x and ca.y == cb.y
end

--- @return number
-- Measure horizontal plus vertical distance (Manhattan distance).
function Vector2D:l1Norm()
    return math.abs(self.x) + math.abs(self.y)
end

--- @return number
-- Measure straight-line distance using the Pythagorean formula.
function Vector2D:l2Norm()
    return math.sqrt(self.x * self.x + self.y * self.y)
end

--- @return number
-- Use the larger coordinate distance; useful for checking a square neighborhood.
function Vector2D:lInfNorm()
    return math.max(math.abs(self.x), math.abs(self.y))
end

